## 3. State Management with `@ngrx/signals`

Use **Classic Mode** with `@ngrx/signals` `WorkflowStore` for strict 1:1 synchronization with Backend Dapper Snapshots.

```typescript
// workflow.store.ts
import { signalStore, withState, withMethods, patchState } from '@ngrx/signals';
import { inject } from '@angular/core';
import { FCreateConnectionEvent, FMoveNodesEvent } from '@foblex/flow';
import { WorkflowApiService } from '../services/workflow-api.service';

export const WorkflowStore = signalStore(
  { providedIn: 'root' },
  withState(() => ({
    workflowId: 0,
    name: '',
    nodes: [] as WorkflowNodeDto[],
    edges: [] as WorkflowEdgeDto[],
    selectedNodeId: null as string | null,
    isDirty: false,
    past: [] as Array<{ nodes: WorkflowNodeDto[]; edges: WorkflowEdgeDto[] }>,
    future: [] as Array<{ nodes: WorkflowNodeDto[]; edges: WorkflowEdgeDto[] }>
  })),
  withMethods((store, api = inject(WorkflowApiService)) => ({
    // 1-Shot GET: Nạp đồ thị
    async loadWorkflow(workflowId: number) {
      const res = await api.getDetail(workflowId);
      if (res.success && res.data) {
        patchState(store, {
          workflowId: res.data.workflow_id,
          name: res.data.name,
          nodes: res.data.nodes || [],
          edges: res.data.edges || [],
          isDirty: false,
          past: [],
          future: []
        });
      }
    },

    // 1-Tx POST: Lưu snapshot
    async saveSnapshot() {
      const payload = {
        workflow_id: store.workflowId(),
        nodes: store.nodes(),
        edges: store.edges()
      };
      const res = await api.saveSnapshot(payload);
      if (res.success) {
        patchState(store, { isDirty: false });
      }
    },

    // Xử lý sự kiện kéo nối từ Foblex Flow
    handleCreateConnection(event: FCreateConnectionEvent) {
      const sourceKey = event.fSourceId.replace('-out', '');
      const targetKey = event.fTargetId.replace('-in', '');

      const newEdge: WorkflowEdgeDto = {
        workflow_edge_id: 0,
        edge_key: `edge-${Date.now()}`,
        source_node_key: sourceKey,
        target_node_key: targetKey,
        source_handle: 'out',
        target_handle: 'in'
      };

      patchState(store, (state) => ({
        past: [...state.past.slice(-29), { nodes: state.nodes, edges: state.edges }],
        future: [],
        edges: [...state.edges, newEdge],
        isDirty: true
      }));
    },

    // Xử lý di chuyển Node
    handleMoveNodes(event: FMoveNodesEvent) {
      patchState(store, (state) => ({
        past: [...state.past.slice(-29), { nodes: state.nodes, edges: state.edges }],
        future: [],
        nodes: state.nodes.map((node) => {
          const match = event.fNodes.find((m) => m.fNodeId === node.node_key);
          return match ? { ...node, position_x: match.fPosition.x, position_y: match.fPosition.y } : node;
        }),
        isDirty: true
      }));
    }
  }))
);
```

